def merge_sorted_streams(*streams):
    if not streams:
        return
    # Collect all items from all streams into a single list, preserving order
    all_items = []
    for stream in streams:
        for item in stream:
            all_items.append(item)
    # Sort by key, then by original index (to handle same key across streams)
    # We need to keep track of original index to ensure later occurrences win
    indexed = [(i, item) for i, item in enumerate(all_items)]
    indexed.sort(key=lambda x: (x[1][0], x[0]))
    # Now iterate and keep only the last value for each key
    result = []
    last_key = None
    for _, (key, value) in indexed:
        if key != last_key:
            result.append((key, value))
            last_key = key
    for item in result:
        yield item
